# Exercise: Rocket Class

class Rocket:
    def __init__(self, name):
        self.name = name
    def launch(self):
        print(self.name, "launched!")

r1 = Rocket("Cosmo-1")
r1.launch()

# Exercise: Bank Account

class BankAccount:
    def __init__(self, owner, balance=0):
        self.owner = owner
        self.balance = balance
    def deposit(self, amount):
        self.balance += amount
        print(f"Deposited ${amount}. New Balance: ${self.balance}")

acc = BankAccount("Explorer", 100)
acc.deposit(50)

# Exercise: Space Explorer Character

class Character:
    def __init__(self, name, hp=100):
        self.name = name
        self.hp = hp
    def take_damage(self, dmg):
        self.hp = max(0, self.hp - dmg)
        print(f"{self.name} took {dmg} damage! Remaining HP: {self.hp}")

hero = Character("Vanguard")
hero.take_damage(25)
